List<Account> accounts = new List<Account>{new Account(Name = 'Cursor Sync One'), new Account(Name = 'Cursor Sync Two')};
insert accounts;
Set<Id> accountIds = new Set<Id>{accounts[0].Id, accounts[1].Id};
Database.PaginationCursor page = Database.getPaginationCursor('SELECT Id, Name FROM Account WHERE Id IN :accountIds ORDER BY Name');
Database.CursorFetchResult pageResult = page.fetchPage(0, 2);
System.assertEquals(2, pageResult.getRecords().size());
System.assert(pageResult.getNextIndex() >= 0);
System.assert(pageResult.getNumDeletedRecords() >= 0);
Boolean done = pageResult.isDone();
System.assertNotEquals(null, done);
System.assert(page.fetchDeleted(0, 1) >= 0);
Datetime start = Datetime.now();
Datetime finish = start.addMinutes(1);
Database.GetDeletedResult deleted = Database.getDeleted('Account', start, finish);
System.assertNotEquals(null, deleted.getDeletedRecords());
Date earliest = deleted.getEarliestDateAvailable();
Date latest = deleted.getLatestDateCovered();
if (earliest != null && latest != null) { System.assert(earliest <= latest); }
